B.JO=new A.br("dart-07-condicionales","Dart b\xe1sico","07 \xb7 if, else if y else","Principiante","Controla qu\xe9 c\xf3digo se ejecuta seg\xfan una o varias condiciones.","Las apps toman decisiones para permisos, formularios y reglas de negocio.","void main() {\n  const nota = 4.2;\n\n  if (nota >= 4.5) {\n    print('Excelente');\n  } else if (nota >= 3.0) {\n    print('Aprobado');\n  } else {\n    print('Reprobado');\n  }\n}",B.Wb,"Clasifica una compra por valor y aplica descuentos distintos.",B.QE,4281652121)
